import 'dart:convert';

import 'package:flutter/material.dart';
import 'package:nib_components/nib_components.dart';
import 'package:nib_motion/nib_motion.dart';

// Embed the existing brand asset so copied examples also work offline.
final nibSwitchLogo = base64Decode(
  '',
);

/// A visible thumb in both states, with the same Nib mark used by the site.
Widget nibSwitchThumb(
  BuildContext context,
  NibSwitchThumbState state, {
  bool square = false,
  Widget? badge,
}) {
  final colors = Theme.of(context).colorScheme;
  return DecoratedBox(
    decoration: BoxDecoration(
      color: colors.surface,
      shape: square ? BoxShape.rectangle : BoxShape.circle,
      borderRadius: square ? BorderRadius.circular(5) : null,
      border: Border.all(color: colors.onSurface, width: 1.5),
    ),
    child: Stack(
      alignment: Alignment.center,
      children: [
        Padding(
          padding: const EdgeInsets.all(3),
          child: Image.memory(
            nibSwitchLogo,
            excludeFromSemantics: true,
            gaplessPlayback: true,
            fit: BoxFit.contain,
          ),
        ),
        if (badge != null) Positioned(right: 0, bottom: 0, child: badge),
        if (state.loading)
          Padding(
            padding: const EdgeInsets.all(2),
            child: CircularProgressIndicator(
              strokeWidth: 2,
              color: colors.primary,
            ),
          ),
      ],
    ),
  );
}

/// Shared site control. NibSwitch owns input, semantics and thumb motion.
class ComponentToggle extends StatelessWidget {
  const ComponentToggle({
    super.key,
    required this.value,
    required this.label,
    required this.onChanged,
    this.showLabel = false,
    this.description,
    this.contentPadding = EdgeInsets.zero,
  });
  final bool value;
  final String label;
  final ValueChanged<bool>? onChanged;
  final bool showLabel;
  final String? description;
  final EdgeInsetsGeometry contentPadding;

  @override
  Widget build(BuildContext context) {
    final colors = Theme.of(context).colorScheme;
    return Theme(
      data: Theme.of(context).copyWith(
        extensions: [
          ...Theme.of(context).extensions.values.where((e) => e is! NibTheme),
          NibTheme.of(context).copyWith(
            primary: colors.primary,
            border: colors.outline,
            foreground: colors.onSurface,
            mutedForeground: colors.onSurfaceVariant,
          ),
        ],
      ),
      child: NibSwitch(
        value: value,
        onChanged: onChanged,
        semanticLabel: label,
        label: showLabel ? label : null,
        description: description,
        contentPadding: contentPadding,
        animated: !NibMotionConfig.watchReducedMotion(context),
        transition: const NibTransition(
          duration: Duration(milliseconds: 220),
          curve: Curves.easeOutCubic,
        ),
        trackWidth: 64,
        trackHeight: 36,
        thumbBuilder: nibSwitchThumb,
      ),
    );
  }
}
